import { useCallback, useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { addLocalDays, createTranslator, localDateInZone, nowEpoch, zoneCity } from "@dcortex/canvas-format";
import {
  ConsoleKpiCard,
  ConsoleKpiGrid,
  ConsoleLayout,
  DeskBrand,
  DeskCloseButton,
  DeskDatePicker,
  DeskFrame,
  DeskIconButton,
  DeskKpiCard,
  DeskKpiStrip,
  DeskProfileButton,
  JumpMenu,
  MonitorMatrix,
  NavSegmentGroup,
  TaskSidebar,
  deskIcons,
  type CrewGroup,
} from "@dcortex/canvas-ui";
import { ApiError, type ApiClient } from "../api/client.js";
import { useSessionPresentation, useSessionUser } from "../api/readPlane.js";
import { consoleLogo, performLogout } from "../ConsoleControls.js";
import { buildConsoleCards, buildTaskSidebar, CONSOLE_KPI_ORDER, type DeskTask, type KpiRead, type KpiReads } from "../desk/consoleModel.js";
import { DeskAlertModal } from "../desk/DeskAlertModal.js";
import { DeskTimelineBoard, type TimelineRead } from "../desk/DeskTimelineBoard.js";
import { DeskBriefBoard, type BriefRead } from "../desk/DeskBriefBoard.js";
import { DeskCrewBoard, type CrewRead } from "../desk/DeskCrewBoard.js";
import { DeskNotesPopup, type ControllerNoteDraft, type NotesRead } from "../desk/DeskNotesPopup.js";
import { mergeNotes, type ControllerNotesResponse, type CrewMemosResponse } from "../desk/notesModel.js";
import { DeskCasePane } from "../desk/DeskCasePane.js";
import { DeskPaneBoundary } from "../desk/DeskPaneBoundary.js";
import { DeskKpiDetail } from "../desk/DeskKpiDetail.js";
import { rowIdentity } from "../desk/rowIdentity.js";
import { applyCheckInConfirmedOverlay, buildMonitorModel, UNBANKED, type DeskMonitorResponse } from "../desk/monitorModel.js";
import { useAcknowledgmentOverlay } from "../api/acknowledgmentOverlay.js";
import { DESK_OPS_KEYS, parseDeskSel, serializeDeskSel, stepBackDeskSel, type DeskOpsKey, type DeskSelection } from "../desk/deskSelection.js";
import { messages } from "../i18n/messages.js";
import { useLaunchpadEnabled } from "../launchpadFlag.js";
import { NAV_VIEWS } from "../nav.js";
import { railEntryVisible } from "../navPermissions.js";
import { useRailAccess } from "../railAccess.js";
import { ViewerZoneSelect } from "../ViewerZoneSelect.js";

/** Controller desk D2 — the Canvas /desk shell, matched to legacy /desk (knowledge-base/features/controller-desk.md
 * §D2). Views-only: every count and state comes from `GET /api/read/desk-monitor`; the one thing computed here is the
 * tenant zone's Today and Tomorrow. D3: an idle Monitor draws the bank × risk matrix. D4a: a strip card, count, chip or
 * "+n unbanked" opens legacy's KPI table for that KPI, bank and severity; the Console tab draws the task sidebar, the
 * eight-card KPI grid and the same tables. A KPI's table and card read the source the desk-monitor echoed. */

type StripCard = DeskMonitorResponse["strip"][number];

/** A card the session cannot see, or that has no meaning for the date, is not shown (legacy hides both). */
const HIDDEN_REASONS = new Set(["not_permitted", "not_today"]);
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
/** Legacy SUPERVISOR_KPI_DASHBOARD_REFRESH_MS (§D2 Decision 7). */
const POLL_MS = 180_000;

export function Desk({
  client,
  onNavigate,
  now = nowEpoch,
  pollMs = POLL_MS,
  visibility = () => document.visibilityState,
}: {
  client: ApiClient;
  onNavigate?: (path: string) => void;
  now?: () => number;
  pollMs?: number;
  visibility?: () => DocumentVisibilityState;
}) {
  const ctx = client.presentation();
  const renderCtx = ctx ?? { timezone: "UTC", locale: "en", currency: "USD" };
  const t = createTranslator(renderCtx.locale, messages);
  const user = useSessionUser(client);
  const sessionPresentation = useSessionPresentation(client);
  const access = useRailAccess();
  const [params, setParams] = useSearchParams();

  // viewer-timezone §5.2 — the desk stays on the airline's OPERATIONAL day: its banks sit minutes from the airline's own
  // midnight, so the viewer's zone (`renderCtx.timezone`, which only decides how instants read) is NOT consulted here. A
  // server older than S1 sends no operationalTimezone; its `timezone` then IS the tenant zone.
  const operationalZone = ctx?.operationalTimezone ?? renderCtx.timezone;
  const today = localDateInZone(now(), operationalZone);
  const tomorrow = addLocalDays(today, 1);
  const rawDate = params.get("date");
  const date = rawDate && DATE_RE.test(rawDate) ? rawDate : today;
  const selection = parseDeskSel(params.get("sel"));
  const checkinConfirmedOverlay = useAcknowledgmentOverlay("checkin", date);

  const setUrl = useCallback(
    (next: { date?: string; sel?: DeskSelection }) => {
      setParams(
        (prev) => {
          const p = new URLSearchParams(prev);
          if (next.date !== undefined) p.set("date", next.date);
          if (next.sel !== undefined) {
            const token = serializeDeskSel(next.sel);
            if (token) p.set("sel", token);
            else p.delete("sel");
          }
          return p;
        },
        { replace: true },
      );
    },
    [setParams],
  );

  // a link carries the zone it was made in (viewer-timezone §4.1): choosing a zone puts `tz` in the URL, choosing the airline
  // day (`undefined`) takes it out. Applied to the client at app start by `bootstrapViewerZone`; this only keeps the URL honest.
  const setUrlZone = useCallback(
    (zone: string | undefined) => {
      setParams(
        (prev) => {
          const p = new URLSearchParams(prev);
          if (zone) p.set("tz", zone);
          else p.delete("tz");
          return p;
        },
        { replace: true },
      );
    },
    [setParams],
  );

  const [data, setData] = useState<DeskMonitorResponse>();
  const [failure, setFailure] = useState<"error" | "notConfigured">();
  const [refreshingKey, setRefreshingKey] = useState<string>();

  const load = useCallback(async () => {
    try {
      const snap = await client.get<DeskMonitorResponse>(`/api/read/desk-monitor?date=${date}`);
      setData(snap);
      setFailure(undefined);
    } catch (err) {
      if (err instanceof Error && err.message === "unauthenticated") return; // routed to login
      setData(undefined);
      setFailure(err instanceof ApiError && err.status === 404 ? "notConfigured" : "error");
    }
  }, [client, date]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (visibility() === "visible") void load();
    }, pollMs);
    return () => clearInterval(timer);
  }, [load, pollMs, visibility]);

  const refreshCard = (key: string) => {
    setRefreshingKey(key);
    void load().finally(() => setRefreshingKey(undefined));
  };

  const [jumpOpen, setJumpOpen] = useState(false);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (target && (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName))) return;
      if (e.key === "j" || e.key === "J") setJumpOpen(true);
      if (e.key === "Escape") {
        if (jumpOpen) setJumpOpen(false);
        else if (selection.type !== "idle") setUrl({ sel: stepBackDeskSel(selection) });
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [jumpOpen, selection, setUrl]);

  const [theme, setTheme] = useState<"dark" | "light">(() => (document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark"));
  const toggleTheme = () => {
    const next = theme === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    setTheme(next);
  };

  const locales = sessionPresentation?.supportedLocales?.length ? sessionPresentation.supportedLocales : [renderCtx.locale];
  const activeLocale = locales.find((l) => l.toLowerCase() === renderCtx.locale.toLowerCase()) ?? locales.find((l) => l.slice(0, 2).toLowerCase() === renderCtx.locale.slice(0, 2).toLowerCase()) ?? locales[0]!;

  const launchpadEnabled = useLaunchpadEnabled();
  const jumpItems = useMemo(
    () => NAV_VIEWS.filter((v) => v.id !== "console" && railEntryVisible(v.id, access) && (v.id !== "launchpad" || launchpadEnabled)).map((v) => ({ id: v.path, label: t(v.labelKey), icon: v.icon })),
    [access, launchpadEnabled, t],
  );

  /** D4c — the identity behind a chip: the chip groups a cell's items, so its first item names the row. */
  const chipIdentity = (res: DeskMonitorResponse, row: string, bank: string, chipId: string): string | undefined => {
    const cell = res.rows.find((r) => r.key === row);
    if (!cell || cell.status !== "ok") return undefined;
    const items = cell.cells.find((c) => c.bankId === bank)?.items ?? [];
    const match = items.find((i) => {
      const d = i.detail as Record<string, unknown>;
      const flightRoute = `${String(d.flight)}|${String(d.dep)}|${String(d.arr)}`;
      return d.legId === chipId || d.pairingKey === chipId.replace(/#\d+$/, "") || d.flight === chipId || flightRoute === chipId || `${String(d.crewMemberId)}|${String(d.ruleCode)}` === chipId;
    });
    return match ? rowIdentity.item(match.detail) : undefined;
  };

  const selectedKey = selection.type === "ops" ? selection.key : undefined;
  const selectCard = (key: DeskOpsKey) => setUrl({ sel: selectedKey === key ? { type: "idle" } : { type: "ops", key } });

  // The OPS strip reads the overlay-adjusted snapshot (§ applyCheckInConfirmedOverlay) so its "Check-in
  // Gaps" count matches the Monitor grid below it; chipIdentity/DeskAlertModal below deliberately keep
  // reading the RAW data instead — an already-open modal's crew table must keep showing a just-confirmed
  // row (relabeled, not removed), only the grid's own chips/counts should drop it.
  const stripData = data ? applyCheckInConfirmedOverlay(data, checkinConfirmedOverlay) : data;
  const cards = (stripData?.strip ?? []).filter((c): c is StripCard & { key: DeskOpsKey } => DESK_OPS_KEYS.includes(c.key as DeskOpsKey) && !(c.status === "unavailable" && HIDDEN_REASONS.has(c.reason)));

  // ── D4a — each KPI's read of the source the desk-monitor echoed (legality adds its pilot and cabin reads) ──
  const [reads, setReads] = useState<KpiReads>({});
  const [consoleRefreshing, setConsoleRefreshing] = useState<string>();
  const readKpi = useCallback(
    async (res: DeskMonitorResponse, key: DeskOpsKey) => {
      const source = res.sources?.[key];
      if (!source) {
        setReads((cur) => ({ ...cur, [key]: { status: "error" } }));
        return;
      }
      const url = (extra: Record<string, string> = {}) => {
        const qs = new URLSearchParams({ ...source.query, ...extra }).toString();
        return qs ? `${source.path}?${qs}` : source.path;
      };
      try {
        const [main, pilot, cabin] = await Promise.all([client.get<unknown>(url()), ...(key === "ftl" ? [client.get<unknown>(url({ filter: "pilot" })), client.get<unknown>(url({ filter: "cabin" }))] : [])]);
        const next: KpiRead = key === "ftl" ? { status: "ok", data: main, pilot, cabin } : { status: "ok", data: main };
        setReads((cur) => ({ ...cur, [key]: next }));
      } catch (err) {
        if (err instanceof Error && err.message === "unauthenticated") return;
        setReads((cur) => ({ ...cur, [key]: { status: "error" } }));
      }
    },
    [client],
  );
  // ── D5 — the Timeline's own read: the flight-crew plane for the desk's date, plus flight-status for the
  // aircraft and the delay the crew plane does not carry. The plane already banked every leg (invariant 3).
  const [timeline, setTimeline] = useState<TimelineRead>({ status: "loading" });
  const onTimeline = selection.type === "timeline";
  useEffect(() => {
    if (!onTimeline) return;
    let live = true;
    setTimeline({ status: "loading" });
    void (async () => {
      try {
        const [crew, flightStatus] = await Promise.all([
          client.get<never>(`/api/read/flight-crew?date=${date}`),
          client.get<never>(`/api/read/flight-status?date=${date}`).catch(() => undefined),
        ]);
        if (live) setTimeline({ status: "ok", crew, ...(flightStatus ? { status_: flightStatus } : {}) });
      } catch (err) {
        if (err instanceof Error && err.message === "unauthenticated") return;
        if (live) setTimeline({ status: "error" });
      }
    })();
    return () => {
      live = false;
    };
  }, [client, onTimeline, date]);

  // ── D6 — the two remaining tabs, each a desk view over its own plane (ruling BC) ──
  const [crew, setCrew] = useState<CrewRead>({ status: "loading" });
  const onCrew = selection.type === "crew";
  const onBrief = selection.type === "brief";
  useEffect(() => {
    if (!onCrew) return;
    let live = true;
    setCrew({ status: "loading" });
    void (async () => {
      try {
        const data = await client.get<never>(`/api/read/crew-status?date=${date}`);
        if (live) setCrew({ status: "ok", data });
      } catch (err) {
        if (err instanceof Error && err.message === "unauthenticated") return;
        if (live) setCrew({ status: "error" });
      }
    })();
    return () => {
      live = false;
    };
  }, [client, onCrew, date]);

  // ── D6 + D7 — ONE read of each notes source per date, shared by the Day brief tab and the Notes badge.
  // Two consumers of the same plane must not become two requests: the badge would then disagree with the tab
  // it counts, and the desk would ask the BFF the same question twice on every load.
  const [notesOpen, setNotesOpen] = useState(false);
  const [notesEpoch, setNotesEpoch] = useState(0);
  const [notes, setNotes] = useState<NotesRead>({ status: "loading" });
  useEffect(() => {
    let live = true;
    setNotes({ status: "loading" });
    void (async () => {
      const [memos, brief, crewMemos, controller] = await Promise.all([
        client.get<never>(`/api/read/flight-memos?date=${date}`).catch(() => undefined),
        client.get<never>("/api/read/shift-handover").catch(() => undefined),
        client.get<CrewMemosResponse>(`/api/read/crew-memos?date=${date}`).catch(() => undefined),
        client.get<ControllerNotesResponse>(`/api/read/controller-notes?date=${date}`).catch(() => undefined),
      ]);
      if (!live) return;
      const crewFailed = !crewMemos || (crewMemos.status === "unavailable" && crewMemos.reason === "failed");
      const controllerOk = controller?.status === "ok" ? controller : undefined;
      // A stub or an unmounted route answers a body with no status. That is not a failed read.
      const controllerFailed = controller == null || controller.status === "failed";
      setNotes({
        status: "ok",
        ...(memos ? { memos } : { memosFailed: true }),
        ...(brief ? { brief } : { briefFailed: true }),
        ...(crewMemos?.status === "ok" ? { crewMemos } : {}),
        ...(crewFailed ? { crewMemosFailed: true } : {}),
        ...(controllerOk ? { controllerNotes: controllerOk } : {}),
        ...(controllerFailed ? { controllerNotesFailed: true } : {}),
      });
    })();
    return () => {
      live = false;
    };
  }, [client, date, notesEpoch]);

  /** The Day brief tab reads the same brief the badge counted — one request, one truth. */
  const brief: BriefRead = useMemo(() => {
    if (notes.status === "loading") return { status: "loading" };
    if (notes.status === "ok" && notes.brief) return { status: "ok", data: notes.brief };
    return { status: "error" };
  }, [notes]);

  /** The badge is a COUNT, not a promise: if any source failed it is absent rather than understating. */
  const notesCount = useMemo(() => {
    if (notes.status !== "ok" || notes.memosFailed || notes.briefFailed || notes.crewMemosFailed || notes.controllerNotesFailed) return null;
    return mergeNotes({
      ...(notes.memos ? { memos: notes.memos } : {}),
      ...(notes.brief ? { brief: notes.brief } : {}),
      ...(notes.crewMemos?.status === "ok" ? { crewMemos: notes.crewMemos } : {}),
      ...(notes.controllerNotes?.status === "ok" ? { controllerNotes: notes.controllerNotes } : {}),
    }, t).length;
  }, [notes, t]);

  // D6 ruling BG — five tabs need ~1121px; below it the view tabs keep their icons and drop their words.
  const [compactTabs, setCompactTabs] = useState(false);
  useEffect(() => {
    const check = () => setCompactTabs(window.innerWidth < 1121);
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  const neededKeys = (selection.type === "console" && !selection.caseTaskId ? CONSOLE_KPI_ORDER : selection.type === "ops" ? [selection.key] : []).join(",");
  useEffect(() => {
    if (!data || !neededKeys) return;
    for (const key of neededKeys.split(",") as DeskOpsKey[]) void readKpi(data, key);
  }, [data, neededKeys, readKpi]);
  const refreshConsoleCard = (key: DeskOpsKey) => {
    if (!data) return;
    setConsoleRefreshing(key);
    void readKpi(data, key).finally(() => setConsoleRefreshing(undefined));
  };

  // ── D4a — the Console task sidebar ──
  const [tasks, setTasks] = useState<DeskTask[]>([]);
  const [tasksRefreshing, setTasksRefreshing] = useState(false);
  const [taskTab, setTaskTab] = useState<"review" | "done">("review");
  const [taskSearch, setTaskSearch] = useState("");
  const [taskGroups, setTaskGroups] = useState<Record<string, CrewGroup>>({});
  const onConsole = selection.type === "console";
  const loadTasks = useCallback(async () => {
    try {
      const res = await client.get<{ tasks: DeskTask[] }>("/api/tasks");
      setTasks(res.tasks ?? []);
    } catch {
      setTasks([]);
    }
  }, [client]);
  useEffect(() => {
    if (onConsole) void loadTasks();
  }, [onConsole, loadTasks, data]);

  // D4b-1 — a task opens its case pane inside the Console (ruling S is superseded for the sidebar; the Monitor's
  // uncrewed badges still deep-link into review until D4b-3).
  const openTask = (taskId: string) => setUrl({ sel: { type: "console", caseTaskId: taskId } });

  const detail = (kpi: DeskOpsKey, bank: string | undefined, sev: "crit" | "warn" | "unknown" | undefined, heading: boolean, onBank: (bank: string | undefined) => void, onShowAll: () => void) => (
    <DeskPaneBoundary key={`${kpi}`} fallback={<p className="desk-state">{t("desk.error")}</p>}>
      <DeskKpiDetail kpi={kpi} read={reads[kpi] ?? { status: "loading" }} res={data!} bank={bank} sev={sev} heading={heading} ctx={renderCtx} t={t} onBank={onBank} onShowAll={onShowAll} onTask={openTask} client={client} onRefresh={() => void load()} {...(onNavigate ? { onNavigate } : {})} {...(data?.positionGroups ? { positionGroups: data.positionGroups } : {})} />
    </DeskPaneBoundary>
  );

  const main = (() => {
    if (failure === "notConfigured") return <p className="desk-state">{t("desk.notConfigured")}</p>;
    if (failure === "error") return <p className="desk-state">{t("desk.error")}</p>;
    if (!data) return <p className="desk-state">{t("desk.loading")}</p>;
    if (selection.type === "crew") return <DeskCrewBoard read={crew} ctx={renderCtx} t={t} />;
    if (selection.type === "brief") {
      return (
        <DeskBriefBoard
          read={brief}
          ctx={renderCtx}
          t={t}
          onExport={(doc) => {
            // the BFF's bytes, verbatim — Canvas assembles no second document (decision 4)
            const url = URL.createObjectURL(new Blob([doc.body], { type: doc.contentType }));
            const a = document.createElement("a");
            a.href = url;
            a.download = doc.filename;
            a.click();
            URL.revokeObjectURL(url);
          }}
        />
      );
    }
    if (selection.type === "timeline") {
      return (
        <DeskTimelineBoard
          read={timeline}
          {...(selection.bank ? { bank: selection.bank } : {})}
          banks={data.banks}
          {...(data.currentBankId ? { currentBankId: data.currentBankId } : {})}
          positionGroups={data.positionGroups}
          ctx={renderCtx}
          t={t}
          onBank={(bank) => setUrl({ sel: bank ? { type: "timeline", bank } : { type: "timeline" } })}
          client={client}
        />
      );
    }
    if (selection.type === "console") {
      const sidebar = buildTaskSidebar(tasks, { date, tab: taskTab, search: taskSearch, groups: taskGroups }, renderCtx, t);
      const kpi = selection.kpi;
      const caseTaskId = selection.caseTaskId;
      return (
        <ConsoleLayout
          sidebar={
            <TaskSidebar
              tabs={{ review: { label: t("desk.console.tab.review"), count: sidebar.tabs.review }, done: { label: t("desk.console.tab.done"), count: sidebar.tabs.done } }}
              activeTab={taskTab}
              onTab={setTaskTab}
              onRefresh={() => {
                setTasksRefreshing(true);
                void loadTasks().finally(() => setTasksRefreshing(false));
              }}
              refreshing={tasksRefreshing}
              refreshLabel={t("desk.console.refresh")}
              search={{ value: taskSearch, onChange: setTaskSearch, placeholder: t("desk.console.search.placeholder"), ariaLabel: t("desk.console.search.aria"), clearLabel: t("desk.console.search.clear") }}
              {...(caseTaskId ? { selectedTaskId: caseTaskId } : {})}
              categories={sidebar.categories.map(({ groupFilter, ...cat }) => (groupFilter ? { ...cat, groupFilter: { ...groupFilter, ariaLabel: t("desk.console.groupAria"), noMatchLabel: t("desk.console.groupNoMatch") } } : cat))}
              emptyLabel={t("desk.console.empty")}
              onTask={openTask}
              onGroup={(category, group) => setTaskGroups((cur) => ({ ...cur, [category]: group }))}
            />
          }
        >
          {caseTaskId ? (
            <DeskPaneBoundary key={caseTaskId} fallback={<p className="desk-state">{t("desk.error")}</p>}>
              <DeskCasePane
                client={client}
                taskId={caseTaskId}
                staleAfterMinutes={data.staleAfterMinutes ?? 30}
                now={now}
                permissions={access.state === "known" ? [...access.keys] : []}
                {...(sessionPresentation?.overrideReasonLabels ? { overrideReasonLabels: sessionPresentation.overrideReasonLabels } : {})}
                swapEnabled={sessionPresentation?.swapEnabled === true}
                onClose={() => setUrl({ sel: { type: "console" } })}
                onDone={() => {
                  setUrl({ sel: { type: "console" } });
                  void loadTasks();
                }}
              />
            </DeskPaneBoundary>
          ) : (
          <>
          <ConsoleKpiGrid ariaLabel={t("desk.console.kpisAria")}>
            {buildConsoleCards(data, reads, t, checkinConfirmedOverlay).map((card) => (
              <ConsoleKpiCard
                key={card.key}
                label={card.label}
                value={card.value}
                {...(card.loading ? { loading: true } : {})}
                {...(card.hint ? { hint: card.hint } : {})}
                selected={kpi === card.key}
                onSelect={() => setUrl({ sel: kpi === card.key ? { type: "console" } : { type: "console", kpi: card.key } })}
                onRefresh={() => refreshConsoleCard(card.key)}
                refreshing={consoleRefreshing === card.key}
                refreshLabel={t("desk.console.refresh")}
                left={card.left}
                right={card.right}
              />
            ))}
          </ConsoleKpiGrid>
          {kpi &&
            detail(
              kpi,
              selection.bank,
              undefined,
              true,
              (bank) => setUrl({ sel: { type: "console", kpi, ...(bank ? { bank } : {}) } }),
              () => setUrl({ sel: { type: "console", kpi } }),
            )}
          </>
          )}
        </ConsoleLayout>
      );
    }
    if (selection.type === "ops") {
      const key = selection.key;
      const openItem = selection.bank && selection.item ? { bank: selection.bank, item: selection.item } : undefined;
      return (
        <>
          <DeskCloseButton label={t("desk.close")} onClick={() => setUrl({ sel: { type: "idle" } })} />
          {openItem && (
            <DeskAlertModal
              client={client}
              res={data}
              row={key}
              bank={openItem.bank}
              item={openItem.item}
              ctx={renderCtx}
              t={t}
              onClose={() => setUrl({ sel: { type: "ops", key, bank: openItem.bank } })}
              {...(onNavigate ? { onNavigate } : {})}
            />
          )}
          {detail(
            key,
            selection.bank,
            selection.sev,
            false,
            (bank) => setUrl({ sel: { type: "ops", key, ...(bank ? { bank } : {}) } }),
            () => setUrl({ sel: { type: "ops", key } }),
          )}
        </>
      );
    }
    const model = buildMonitorModel(applyCheckInConfirmedOverlay(data, checkinConfirmedOverlay), renderCtx, t);
    return (
      <MonitorMatrix
        cornerLabel={t("desk.monitor.corner")}
        pastLabel={t("desk.monitor.past")}
        nowLabel={t("desk.monitor.now")}
        banks={model.banks}
        rows={model.rows.map(({ unbankedCount, ...row }) =>
          unbankedCount > 0 ? { ...row, unbanked: { label: t("desk.monitor.unbanked", { n: unbankedCount }), onClick: () => setUrl({ sel: { type: "ops", key: row.key, bank: UNBANKED } }) } } : row,
        )}
        onCount={(row, bank, sev) => setUrl({ sel: { type: "ops", key: row, bank, sev } })}
        // D4c (ruling AS) — a chip opens THAT item's modal over its table.
        onChip={(row, bank, chipId) => {
          const item = chipIdentity(data, row, bank, chipId);
          setUrl({ sel: { type: "ops", key: row, bank, ...(item ? { item } : {}) } });
        }}
        onBadge={(_row, badgeId) => openTask(badgeId.replace(/#\d+$/, ""))}
      />
    );
  })();

  const canWriteControllerNote = access.state === "known" && access.keys.has("controller_notes:write");
  const notesDrawer = notesOpen ? (
    <DeskNotesPopup
      read={notes}
      date={date}
      banks={data?.banks ?? []}
      ctx={renderCtx}
      t={t}
      onClose={() => setNotesOpen(false)}
      {...(canWriteControllerNote
        ? {
            onCompose: async (draft: ControllerNoteDraft) => {
              await client.post("/api/controller-notes", { ...draft, operationalDate: date });
              setNotesEpoch((n) => n + 1);
            },
          }
        : {})}
    />
  ) : null;

  return (
    <DeskFrame
      brand={<DeskBrand name={ctx?.customerName ?? sessionPresentation?.customerName ?? sessionPresentation?.tenantId ?? ""} logo={consoleLogo(t)} />}
      center={
        <>
          <DeskDatePicker
            value={date}
            today={today}
            tomorrow={tomorrow}
            locale={renderCtx.locale}
            labels={{
              group: t("desk.date.group"),
              today: t("desk.date.today"),
              tomorrow: t("desk.date.tomorrow"),
              pick: t("desk.date.pick"),
              hint: t("desk.date.hint", { city: zoneCity(operationalZone, client.presentation()) }),
              cancel: t("desk.date.cancel"),
              apply: t("desk.date.apply"),
              prevMonth: t("desk.date.prevMonth"),
              nextMonth: t("desk.date.nextMonth"),
            }}
            onChange={(next) => setUrl({ date: next })}
          />
          <NavSegmentGroup
            ariaLabel={t("desk.view.aria")}
            items={[
              { id: "monitor", label: t("desk.view.monitor"), icon: deskIcons.monitor },
              { id: "console", label: t("desk.view.console"), icon: deskIcons.console },
              { id: "timeline", label: t("desk.view.timeline"), icon: deskIcons.clock },
              { id: "crew", label: t("desk.view.crew"), icon: deskIcons.user },
              { id: "brief", label: t("desk.view.brief"), icon: deskIcons.console },
            ]}
            compact={compactTabs}
            active={onConsole ? "console" : onTimeline ? "timeline" : onCrew ? "crew" : onBrief ? "brief" : "monitor"}
            onSelect={(id) =>
              setUrl({ sel: id === "console" ? { type: "console" } : id === "timeline" ? { type: "timeline" } : id === "crew" ? { type: "crew" } : id === "brief" ? { type: "brief" } : { type: "idle" } })
            }
          />
          <JumpMenu label={t("desk.jump")} items={jumpItems} open={jumpOpen} onOpenChange={setJumpOpen} onSelect={(path) => onNavigate?.(path)} />
          <button type="button" className="desk-notes-btn" aria-label={t("desk.notes.button")} onClick={() => setNotesOpen(true)}>
            {deskIcons.note}
            <span>{t("desk.notes.button")}</span>
            {notesCount !== null && notesCount > 0 && (
              <sup className="desk-notes-badge" data-testid="notes-badge">
                {notesCount > 99 ? "99+" : notesCount}
              </sup>
            )}
          </button>
        </>
      }
      right={
        <>
          <ViewerZoneSelect client={client} t={t} onChange={setUrlZone} />
          <NavSegmentGroup
            role="radiogroup"
            uppercase
            ariaLabel={t("desk.lang")}
            items={locales.map((l) => ({ id: l, label: l.slice(0, 2).toLowerCase() }))}
            active={activeLocale}
            onSelect={(locale) => client.setPresentationOverride({ locale })}
          />
          <DeskIconButton label={t("dash.toggleTheme")} onClick={toggleTheme}>
            {theme === "dark" ? deskIcons.sun : deskIcons.moon}
          </DeskIconButton>
          <DeskProfileButton user={user ?? ""} onLogout={() => void performLogout(client)} labels={{ userMenu: t("desk.userMenu"), logout: t("shell.logout") }} />
        </>
      }
      topPane={
        onConsole ? undefined : (
        <DeskKpiStrip opsLabel={t("desk.ops")} ariaLabel={t("desk.kpisAria")}>
          {cards.map((c) => (
            <DeskKpiCard
              key={c.key}
              label={t(`desk.kpi.${c.key}`)}
              count={c.status === "ok" ? c.count : null}
              selected={selectedKey === c.key}
              onSelect={() => selectCard(c.key)}
              onRefresh={() => refreshCard(c.key)}
              refreshing={refreshingKey === c.key}
              refreshLabel={t("desk.refresh")}
              {...(c.status === "unavailable" ? { title: t(`desk.unavailable.${c.reason}`) } : {})}
            />
          ))}
        </DeskKpiStrip>
        )
      }
    >
      {main}
      {notesDrawer}
    </DeskFrame>
  );
}

import { useEffect, useMemo, useState } from "react";
import { DeskModal, DeskTimeline, NavSegmentGroup } from "@dcortex/canvas-ui";
import { formatInstant, type RenderContext, type Translator } from "@dcortex/canvas-format";
import type { ApiClient } from "../api/client.js";
import { CheckInCrewTable } from "./CheckInCrewTable.js";
import { FlightSearchField } from "./FlightSearchField.js";
import { bankTabs, filterTimelineRows, positionColumns, timelineRows, type PositionGroups, type TimelineFlightCrew, type TimelineStatus } from "./timelineModel.js";
import { isAcknowledged, useAcknowledgmentOverlay } from "../api/acknowledgmentOverlay.js";
import { rowIdentity } from "./rowIdentity.js";

/** Controller desk D5 — the Timeline board (knowledge-base/features/controller-desk.md §D5 Decision 8). The
 * bank tab is the desk's own (it lives in the URL, so a reload restores it); the direction toggle and the search
 * are the operator's own narrowing and stay local. Every fact on a row was decided by the plane. */

export type TimelineRead = { status: "loading" } | { status: "error" } | { status: "ok"; crew: TimelineFlightCrew; status_?: TimelineStatus };

export function DeskTimelineBoard({
  read,
  bank,
  banks,
  currentBankId,
  positionGroups,
  ctx,
  t,
  onBank,
  client,
}: {
  read: TimelineRead;
  bank?: string;
  /** the tenant's windows, as the desk-monitor plane sent them — Canvas prints no hour of its own. */
  banks: ReadonlyArray<{ id: string; startMinute: number; endMinute: number }>;
  currentBankId?: string | null;
  positionGroups: PositionGroups | undefined;
  ctx: RenderContext;
  t: Translator;
  onBank: (bank?: string) => void;
  client?: ApiClient;
}) {
  const [direction, setDirection] = useState<"all" | "departure" | "arrival">("all");
  const [search, setSearch] = useState("");
  const [checkIn, setCheckIn] = useState<"all" | "missing" | "late" | "manual" | "checkedIn">("all");
  const [openLegId, setOpenLegId] = useState<string | null>(null);
  const [gaps, setGaps] = useState<{ day: string; rows: Array<Record<string, unknown>>; manualCheckIn?: boolean; rowNotify?: boolean; findReplacement?: boolean } | null>(null);

  const all = useMemo(() => (read.status === "ok" ? timelineRows(read.crew, read.status_) : []), [read]);
  const columns = useMemo(() => positionColumns(all, positionGroups), [all, positionGroups]);
  // Derived, not stored — so a manual check-in toggled from the nested CheckInCrewTable (which only
  // refreshes `gaps`, not this read) is still reflected the instant it's saved, via the same overlay every
  // other surface reads; a stored snapshot of the clicked row would keep showing "Missing" for that crew
  // member until the Timeline's own next poll, even while a save just confirmed otherwise beside it.
  const open = openLegId ? (all.find((r) => r.legId === openLegId) ?? null) : null;
  const confirmedOverlay = useAcknowledgmentOverlay("checkin", open?.operationalDate ?? "");
  const manualOn = read.status === "ok" && read.crew.manualCheckIn === true;
  const checkInChoice = checkIn === "manual" && !manualOn ? "all" : checkIn;
  const rows = useMemo(
    () => filterTimelineRows(all, { ...(bank ? { bank } : {}), ...(direction === "all" ? {} : { direction }), ...(checkInChoice === "all" ? {} : { checkIn: checkInChoice }), search }),
    [all, bank, direction, checkInChoice, search],
  );

  useEffect(() => {
    if (!open || !client) return;
    let live = true;
    void client.get<Record<string, unknown>>(`/api/read/crew-check-in-gaps?date=${open.operationalDate}`).then((data) => {
      if (!live) return;
      const list = Array.isArray(data.gaps) ? (data.gaps as Array<Record<string, unknown>>) : [];
      setGaps({
        day: typeof data.day === "string" ? data.day : open.operationalDate,
        rows: list.filter((g) => g.flight === open.flight && g.dep === open.dep && g.arr === open.arr),
        ...(data.manualCheckIn === true ? { manualCheckIn: true } : {}),
        ...(data.rowNotify === true ? { rowNotify: true } : {}),
        ...(data.findReplacement === true ? { findReplacement: true } : {}),
      });
    }).catch(() => {
      if (live) setGaps(null);
    });
    return () => {
      live = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- re-fetch on a new target leg only, not on every poll-driven `open` identity change
  }, [openLegId, client]);

  // After a manual check-in toggle the row stays in the gap list (gapKind flips to MANUAL_CHECK_IN) — without
  // re-fetching here, this dialog would keep showing the pre-confirmation state until it's closed and reopened.
  const refreshGaps = () => {
    if (!open || !client) return;
    void client.get<Record<string, unknown>>(`/api/read/crew-check-in-gaps?date=${open.operationalDate}`).then((data) => {
      const list = Array.isArray(data.gaps) ? (data.gaps as Array<Record<string, unknown>>) : [];
      setGaps({
        day: typeof data.day === "string" ? data.day : open.operationalDate,
        rows: list.filter((g) => g.flight === open.flight && g.dep === open.dep && g.arr === open.arr),
        ...(data.manualCheckIn === true ? { manualCheckIn: true } : {}),
        ...(data.rowNotify === true ? { rowNotify: true } : {}),
        ...(data.findReplacement === true ? { findReplacement: true } : {}),
      });
    }).catch(() => {});
  };

  if (read.status === "error") return <p className="tl-empty">{t("desk.timeline.failed")}</p>;

  return (
    <section className="tl-board">
      <div className="tl-controls">
        <NavSegmentGroup
          ariaLabel={t("desk.timeline.bank.aria")}
          role="radiogroup"
          items={bankTabs(banks, t, currentBankId).map((b) => ({ id: b.id, label: b.label }))}
          active={bank ?? "all"}
          onSelect={(id) => onBank(id === "all" ? undefined : id)}
        />
        <NavSegmentGroup
          ariaLabel={t("desk.timeline.dir.aria")}
          role="radiogroup"
          items={[
            { id: "all", label: t("desk.timeline.bank.all") },
            { id: "departure", label: t("desk.timeline.dir.departure") },
            { id: "arrival", label: t("desk.timeline.dir.arrival") },
          ]}
          active={direction}
          onSelect={(id) => setDirection(id as typeof direction)}
        />
        <FlightSearchField value={search} onChange={setSearch} label={t("desk.timeline.search")} placeholder={t("desk.timeline.search")} clearLabel={t("desk.timeline.searchClear")} />
        <select className="tl-search" aria-label={t("desk.timeline.checkIn.aria")} value={checkInChoice} onChange={(e) => setCheckIn(e.target.value as typeof checkIn)}>
          {(["all", "missing", "late", ...(manualOn ? ["manual" as const] : []), "checkedIn"] as const).map((id) => (
            <option key={id} value={id}>{t(`desk.timeline.checkIn.${id}`)}</option>
          ))}
        </select>
      </div>
      {/* a day with flights whose filters leave none has not run out of flights — say which it is. */}
      <DeskTimeline rows={rows} columns={columns} t={t} zone={ctx.timezone} locale={ctx.locale} emptyLabel={t(all.length > 0 ? "desk.timeline.noMatch" : "desk.timeline.empty")} onRowClick={(legId) => { setGaps(null); setOpenLegId(legId); }} />
      {open ? (
        <DeskModal title={t("desk.detail.checkinCrewTitle")} width={1100} closeLabel={t("desk.detail.close")} onClose={() => setOpenLegId(null)}>
          <div data-testid="timeline-flight-dialog">
            <p className="mono">{open.flight} · {open.dep}→{open.arr} · {formatInstant(open.anchorAt, ctx, { style: "time" })}</p>
            <ul>
              {open.crew.map((m) => {
                const confirmed = m.role === "operating" && isAcknowledged(m.checkIn.state === "manual", rowIdentity.checkin({ crewMemberId: m.crewMemberId, flight: open.flight }), confirmedOverlay);
                const state = confirmed ? "manual" : m.checkIn.state;
                return (
                  <li key={m.crewMemberId}>{m.displayName ?? m.positionCode} — {t(`desk.timeline.state.${m.role === "deadhead" ? "deadhead" : state === "notTracked" ? "assignedOnLeg" : state}`)}</li>
                );
              })}
            </ul>
            {gaps && gaps.rows.length > 0 ? (
              <CheckInCrewTable
                gaps={gaps.rows}
                day={gaps.day}
                {...(gaps.manualCheckIn ? { manualCheckIn: true } : {})}
                {...(gaps.rowNotify ? { rowNotify: true } : {})}
                {...(gaps.findReplacement ? { findReplacement: true } : {})}
                {...(client ? { client } : {})}
                t={t}
                time={(iso) => (typeof iso === "string" && iso ? formatInstant(iso, ctx, { style: "time" }) : "—")}
                historyTime={(iso) => (typeof iso === "string" && iso ? formatInstant(iso, ctx, { style: "short" }) : "—")}
                onRefresh={refreshGaps}
              />
            ) : null}
          </div>
        </DeskModal>
      ) : null}
    </section>
  );
}

