/** Closes an open popover on a mousedown outside `ref` (legacy's outside-click behaviour). */
function useOutsideClose(open: boolean, ref: RefObject<HTMLElement | null>, close: () => void): void {
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) close();
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [open, ref, close]);
}

/** `topPane` is the Monitor's OPS strip; the Console tab has none (legacy hides it there, D4a). */
export function DeskFrame({ brand, center, right, topPane, children }: { brand: ReactNode; center: ReactNode; right: ReactNode; topPane?: ReactNode; children: ReactNode }) {
