export interface NavSegmentItem {
  id: string;
  label: string;
  icon?: ReactNode;
}

/** Legacy `NAV_SEGMENT_GROUP` — a 28 px pill of 24 px segments joined by 1 px dividers. */
export function NavSegmentGroup({
  items,
  active,
  onSelect,
  ariaLabel,
  role = "tablist",
  uppercase = false,
  compact = false,
}: {
  items: NavSegmentItem[];
  active: string;
  onSelect: (id: string) => void;
  ariaLabel: string;
  role?: "tablist" | "radiogroup";
  uppercase?: boolean;
  /** controller desk D6 ruling BG — below the width five tabs need, a segment drops its WORD and keeps its
   * icon. The name stays on `aria-label` and `title`, so a screen reader and a hover still have it; a segment
   * with no icon keeps its word rather than becoming an empty button. */
  compact?: boolean;
}) {
  const itemRole = role === "tablist" ? "tab" : "radio";
  return (
    <div className={`nav-seg-group${uppercase ? " uppercase" : ""}${compact ? " compact" : ""}`} role={role} aria-label={ariaLabel}>
      {items.map((item, i) => {
        const on = item.id === active;
        return (
          <span key={item.id} className="nav-seg-slot">
            {i > 0 && <span className="nav-seg-divider" role="separator" aria-hidden="true" />}
            <button
              type="button"
              role={itemRole}
              {...(itemRole === "tab" ? { "aria-selected": on } : { "aria-checked": on })}
              className={`nav-seg${on ? " on" : ""}`}
              aria-label={item.label}
              title={item.label}
              onClick={() => onSelect(item.id)}
            >
              {item.icon}
              {/* compact drops the word only when there is an icon left to carry the meaning */}
              {(!compact || !item.icon) && <span>{item.label}</span>}
            </button>
          </span>
        );
      })}
    </div>
  );
}

export function DeskIconButton({ label, onClick, children }: { label: string; onClick: () => void; children: ReactNode }) {
  return (
    <button type="button" className="nav-ctl nav-ctl-icon" title={label} aria-label={label} onClick={onClick}>
      {children}
    </button>
  );
}

export function DeskCloseButton({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button type="button" className="desk-close" aria-label={label} title={label} onClick={onClick}>
