}

export function DeskProfileButton({ user, onLogout, labels }: { user: string; onLogout: () => void; labels: { userMenu: string; logout: string } }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLSpanElement>(null);
  useOutsideClose(open, ref, () => setOpen(false));
  return (
    <span className="desk-popover-anchor" ref={ref}>
      <button type="button" className={`nav-ctl desk-profile${open ? " open" : ""}`} aria-label={labels.userMenu} aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {deskIcons.user}
        <span className="desk-profile-name">{user}</span>
        {deskIcons.chevronDown}
      </button>
      {open && (
        <div className="desk-menu desk-menu-right" role="menu">
          <button
            type="button"
            role="menuitem"
            className="desk-menu-item danger"
            onClick={() => {
              setOpen(false);
              onLogout();
