  );
}

export interface DeskDateLabels {
  group: string;
  today: string;
  tomorrow: string;
  pick: string;
  hint: string;
  cancel: string;
  apply: string;
  prevMonth: string;
  nextMonth: string;
}

/** Legacy `PanamaSingleDatePicker` in chrome mode: Today · Tomorrow · Pick date, and a month popover with Cancel/Apply.
 * `today`/`tomorrow` are the tenant zone's civil dates, computed by the consumer (never the browser clock here). */
export function DeskDatePicker({ value, today, tomorrow, locale, labels, onChange }: { value: string; today: string; tomorrow: string; locale: string; labels: DeskDateLabels; onChange: (date: string) => void }) {
  const [open, setOpen] = useState(false);
  const [month, setMonth] = useState(value);
  const [draft, setDraft] = useState(value);
  const ref = useRef<HTMLDivElement>(null);
  const close = () => setOpen(false);
  useOutsideClose(open, ref, close);
  const custom = value !== today && value !== tomorrow;
  const openPicker = () => {
    setMonth(value);
    setDraft(value);
    setOpen((o) => !o);
  };
  const segment = (id: string, label: string, on: boolean, onClick: () => void, extra?: ReactNode) => (
    <button key={id} type="button" className={`nav-seg${on ? " on" : ""}`} onClick={onClick}>
      {extra}
      <span>{label}</span>
    </button>
  );
  return (
    <div className="desk-popover-anchor" ref={ref}>
      <div className="nav-seg-group" role="group" aria-label={labels.group}>
        {segment("today", labels.today, value === today, () => onChange(today))}
        <span className="nav-seg-divider" aria-hidden="true" />
        {segment("tomorrow", labels.tomorrow, value === tomorrow, () => onChange(tomorrow))}
        <span className="nav-seg-divider" aria-hidden="true" />
        {segment("pick", custom ? formatLocalDateShort(value) : labels.pick, custom || open, openPicker, deskIcons.calendarDays)}
      </div>
      {open && (
        <div className="desk-cal" role="dialog" aria-label={labels.pick}>
          <p className="desk-cal-hint">{labels.hint}</p>
          <div className="desk-cal-caption">
            <button type="button" className="desk-cal-nav" aria-label={labels.prevMonth} onClick={() => setMonth(addLocalMonths(month, -1))}>
              {deskIcons.chevronLeft}
            </button>
            <span>{formatMonthYear(month, locale)}</span>
            <button type="button" className="desk-cal-nav" aria-label={labels.nextMonth} onClick={() => setMonth(addLocalMonths(month, 1))}>
              {deskIcons.chevronRight}
            </button>
          </div>
          <table className="desk-cal-grid">
            <thead>
              <tr>
                {weekdayNames(locale).map((w, i) => (
                  <th key={i} scope="col">{w}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {monthGrid(month).map((week, wi) => (
                <tr key={wi}>
                  {week.map((day, di) => (
                    <td key={di}>
                      {day && (
                        <button type="button" className={`desk-cal-day${day === today ? " today" : ""}${day === draft ? " selected" : ""}`} onClick={() => setDraft(day)}>
                          {Number(day.slice(8))}
                        </button>
                      )}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
          <div className="desk-cal-footer">
            <button type="button" className="desk-cal-cancel" onClick={close}>{labels.cancel}</button>
            <button
              type="button"
              className="desk-cal-apply"
              onClick={() => {
                close();
                onChange(draft);
              }}
            >
              {labels.apply}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/** Legacy `DeskTopPane` + `DeskOpsKpiStrip`: the "OPS" label and one scrolling row of cards. */
export function DeskKpiStrip({ opsLabel, ariaLabel, children }: { opsLabel: string; ariaLabel: string; children: ReactNode }) {
  return (
    <header className="desk-top-pane">
      <div className="desk-top-scroll">
        <span className="desk-ops">{opsLabel}</span>
        <div className="desk-kpi-list" role="list" aria-label={ariaLabel}>
          {children}
        </div>
      </div>
    </header>
  );
}

/** Legacy `DeskKpiCard`: count over an uppercase label, an optional refresh control, cyan when selected. Severity never
 * colours the card (legacy ignores its tone). An unknown count holds its height with an invisible "0". */
export function DeskKpiCard({
  label,
  count,
  selected = false,
  onSelect,
  onRefresh,
  refreshing = false,
  refreshLabel,
  title,
}: {
  label: string;
  count: number | null;
  selected?: boolean;
  onSelect: () => void;
  onRefresh?: () => void;
  refreshing?: boolean;
  refreshLabel?: string;
  /** why the count is unknown — shown as the tooltip and appended to the accessible name. */
  title?: string;
}) {
  return (
    <div className="desk-kpi">
      <button
        type="button"
        role="listitem"
        aria-pressed={selected}
        className={`desk-kpi-btn${selected ? " selected" : ""}${onRefresh ? " has-refresh" : ""}`}
        onClick={onSelect}
        {...(title ? { title, "aria-label": `${label} — ${title}` } : {})}
      >
        <span className={`desk-kpi-count${count === null ? " invisible" : ""}`} {...(count === null ? { "aria-hidden": true } : {})}>
          {count === null ? "0" : String(count)}
        </span>
        <span className="desk-kpi-label">{label}</span>
      </button>
      {onRefresh && (
        <button
          type="button"
          className={`desk-kpi-refresh${refreshing ? " spinning" : ""}`}
          aria-label={refreshLabel}
          title={refreshLabel}
          disabled={refreshing}
          onClick={(e) => {
            e.stopPropagation();
            onRefresh();
          }}
        >
          {deskIcons.refresh}
        </button>
      )}
    </div>
  );
}

export interface JumpItem {
  id: string;
  label: string;
  icon?: ReactNode;
}

/** Legacy `DeskJumpMenu`: a 28 px control and a menu of destinations. */
export function JumpMenu({ label, items, open, onOpenChange, onSelect }: { label: string; items: JumpItem[]; open: boolean; onOpenChange: (open: boolean) => void; onSelect: (id: string) => void }) {
  const ref = useRef<HTMLSpanElement>(null);
  useOutsideClose(open, ref, () => onOpenChange(false));
  return (
    <span className="desk-popover-anchor" ref={ref}>
      <button type="button" className={`nav-ctl${open ? " open" : ""}`} aria-haspopup="menu" aria-expanded={open} onClick={() => onOpenChange(!open)}>
        {label}
      </button>
      {open && (
        <div className="desk-menu" role="menu" aria-label={label}>
          {items.map((item) => (
            <button
              key={item.id}
              type="button"
              role="menuitem"
              className="desk-menu-item"
              onClick={() => {
                onOpenChange(false);
                onSelect(item.id);
              }}
            >
              {item.icon}
              <span>{item.label}</span>
            </button>
          ))}
        </div>
      )}
    </span>
  );
}

